using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckSumo {
public enum SumoStage{Countdown,Fight,Replay,HeatResult}
public sealed class SumoMatch:SportsEventSession {
 public SumoFighter[] fighters;public Transform ring;public SportsEventCamera broadcast;public SportsMotionReplay replay;public SportsCameraFit fit;public float initialRadius=12,minimumRadius=5,shrinkBegins=23,shrinkSpeed=.16f,maximumHeat=90;public SumoRules rules=new SumoRules();public SumoStage Stage{get;private set;}public float Clock{get;private set;}public float Radius{get;private set;}public float Timer{get;private set;}public int HeatDraws{get;private set;}public int Impacts{get;private set;}public int ShrinkFrames{get;private set;}
 readonly float[] stuck=new float[4],reverse=new float[4],think=new float[4];readonly Vector2[] ai=new Vector2[4];readonly bool[] aiShove=new bool[4];readonly float[] soundCooldown=new float[4];readonly StringBuilder text=new StringBuilder(400);string notice="";
 public override string Title=>"TRUCK SUMO";public override int MinimumPlayers=>2;public override int MaximumPlayers=>4;public override int OptionCount=>1;public override int WeatherCount=>1;public override string OptionLabel=>"FIRST TO FIVE HEATS";public override bool ReplayControls=>Stage==SumoStage.Replay;
 public override string Help=>"Drive and shove opponents out of the raised circular ring. First to five heat wins takes the match. Last truck remaining wins; final ring-outs in the same physics step are a draw with no point. Your authoritative chassis center must cross the visible outer edge: wheel overhang and being airborne inside do not eliminate you. Accelerate, steer, and brake before reversing. Press your assigned ACTION for one forward shove, then wait3.2seconds. A missed shove can carry you over the edge. Stopped trucks can be pushed; there is no stationary counter. At20seconds a warning announces the physical ring shrinking from23seconds toward its minimum. The visible surface and legal radius shrink together. An unresolved90second heat is an explicit draw and replay. Starts rotate each heat. Outfits and eyebrows are cosmetic. Recorded decisive replays offer angle, speed, rewind and skip. Pause/reconnect preserves the match; release and freshly confirm after replacement. No online services.";
 public override string Header=>Title+" · HEAT "+rules.Heat+" · "+(Stage==SumoStage.Countdown?Mathf.CeilToInt(Timer).ToString():Stage==SumoStage.Replay?"ACTUAL REPLAY":Clock.ToString("F1")+"s");
 public override string Status=>Stage==SumoStage.Fight?(Clock>=20?(Clock<shrinkBegins?"THE RING SHRINKS IN "+Mathf.CeilToInt(shrinkBegins-Clock):"RING SHRINKING · WATCH THE EDGE"):"ACTION: SHOVE · THE CHASSIS CENTER DEFINES RING-OUT"):notice;
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[i].color)).Append('>').Append(setup.players[i].name).Append("</color>  ").Append(rules.wins[i]).Append(" / 5   ").Append(!rules.alive[i]?"RING OUT":fighters[i].cooldown>0?"SHOVE "+fighters[i].cooldown.ToString("F1")+"s":"SHOVE READY").Append('\n');return text.ToString();}}
 public override string Results=>(rules.Winner>=0?setup.players[rules.Winner].name+" IS THE SUMO CHAMPION":"MATCH COMPLETE")+"\n\n"+Standings+"\nDrawn heats: "+HeatDraws;
 protected override void BeginGame(){rules.Reset(setup.count);HeatDraws=Impacts=ShrinkFrames=0;replay.Colorize(Array.ConvertAll(setup.players,p=>p.color));BeginHeat();}
 void BeginHeat(){Clock=0;Radius=initialRadius;Timer=2.5f;Stage=SumoStage.Countdown;notice="PREPARE TO SHOVE";ring.gameObject.SetActive(true);ring.localScale=new Vector3(Radius,1,Radius);replay.End();for(int i=0;i<4;i++){fighters[i].gameObject.SetActive(i<setup.count);if(i>=setup.count)continue;float angle=(i/(float)setup.count+(rules.Heat-1)*.137f)*Mathf.PI*2;var position=new Vector3(Mathf.Sin(angle),0,Mathf.Cos(angle))*(Radius-4);position.y=.7f;fighters[i].ResetFighter(position,Quaternion.LookRotation(new Vector3(-position.x,0,-position.z)));fighters[i].truck.TickDrive(Vector2.zero);stuck[i]=reverse[i]=think[i]=soundCooldown[i]=0;ai[i]=Vector2.zero;}replay.ResetRecord();}
 protected override void Simulate(float dt){if(Stage==SumoStage.Countdown){foreach(var fighter in fighters)if(fighter.gameObject.activeSelf)fighter.truck.TickDrive(Vector2.zero);Timer-=dt;if(Timer<=0){Stage=SumoStage.Fight;notice="SHOVE!";}return;}
  if(Stage==SumoStage.Replay){if(replay.Step(dt)||Timer<0){replay.End();Stage=SumoStage.HeatResult;Timer=1.4f;}return;}
  if(Stage==SumoStage.HeatResult){Timer-=dt;if(Timer<=0){if(rules.Complete)EndMatch();else{rules.NextHeat();BeginHeat();}}return;}
  Clock+=dt;float target=Clock>shrinkBegins?Mathf.Max(minimumRadius,initialRadius-(Clock-shrinkBegins)*shrinkSpeed):initialRadius;if(target!=Radius){Radius=target;ring.localScale=new Vector3(Radius,1,Radius);ShrinkFrames++;}
  for(int i=0;i<setup.count;i++){soundCooldown[i]=Mathf.Max(0,soundCooldown[i]-dt);if(!rules.alive[i])continue;var body=fighters[i].truck.body;var center=body.worldCenterOfMass;if(SumoRules.Outside(center.x,center.z,Radius)){rules.Crossed(i);fighters[i].Expression(SumoFace.Eliminated,10,4);fighters[i].SnapFace();fighters[i].truck.Power(false);body.detectCollisions=false;feedback.Play(3,0,true);Pulse(i,.6f,.2f);}}
  if(rules.FinishStep()){ResolveHeat();return;}if(Clock>=maximumHeat){rules.TimeoutDraw();ResolveHeat();return;}
  for(int i=0;i<setup.count;i++)if(rules.alive[i]){Vector2 input=commands[i];bool shove=actions[i];if(setup.players[i].source==BowlingSource.AI){Bot(i,dt);input=ai[i];shove=aiShove[i];}fighters[i].Tick(input,shove,dt);}replay.Record(Clock,((1<<setup.count)-1)|(1<<4));
 }
 void ResolveHeat(){if(rules.HeatWinner<0){HeatDraws++;notice=Clock>=maximumHeat?"TIME LIMIT · DRAW / REHEAT":"SAME-STEP RING OUT · DRAW";}else{fighters[rules.HeatWinner].Expression(SumoFace.Victory,10,5);fighters[rules.HeatWinner].SnapFace();notice=setup.players[rules.HeatWinner].name+" WINS THE HEAT";}feedback.Play(5,0,true);replay.Record(Clock+.051f,((1<<setup.count)-1)|(1<<4));foreach(var fighter in fighters){fighter.truck.Power(false);fighter.truck.body.isKinematic=true;fighter.gameObject.SetActive(false);}ring.gameObject.SetActive(false);Stage=SumoStage.Replay;Timer=0;replay.Begin(Mathf.Max(0,Clock-5));}
 void Bot(int slot,float dt){var t=fighters[slot].truck;var p=t.body.worldCenterOfMass;float radial=new Vector2(p.x,p.z).magnitude;float skill=(int)setup.players[slot].difficulty;stuck[slot]=t.body.linearVelocity.magnitude<.45f?stuck[slot]+dt:0;if(stuck[slot]>2){reverse[slot]=.9f;stuck[slot]=0;}reverse[slot]=Mathf.Max(0,reverse[slot]-dt);think[slot]-=dt;aiShove[slot]=false;if(think[slot]>0)return;think[slot]=Mathf.Lerp(.23f,.08f,skill*.5f);Vector3 target=Vector3.zero;bool danger=radial>Radius-Mathf.Lerp(2.1f,2.9f,skill*.5f);float distance=float.MaxValue;if(!danger)for(int i=0;i<setup.count;i++)if(i!=slot&&rules.alive[i]){var q=fighters[i].truck.body.worldCenterOfMass;float value=(q-p).sqrMagnitude*(1+.08f*Mathf.Sin(slot*13+i*7+rules.Heat));if(value<distance){distance=value;target=q;}}var direction=target-p;direction.y=0;var forward=t.body.rotation*Vector3.forward;float angle=Vector3.SignedAngle(forward,direction,Vector3.up);float steering=Mathf.Clamp(angle/35,-1,1);float throttle=Mathf.Abs(angle)>100?-.75f:Mathf.Abs(angle)>50?.5f:1;if(throttle<0)steering=-steering;if(reverse[slot]>0){throttle=-.8f;steering=slot%2==0?.8f:-.8f;}ai[slot]=new Vector2(steering,throttle);aiShove[slot]=!danger&&direction.magnitude<4.3f&&Mathf.Abs(angle)<Mathf.Lerp(17,28,skill*.5f)&&Vector3.Dot(t.body.linearVelocity,forward)>-.5f&&fighters[slot].cooldown<=0;}
 public void Shoved(int slot){feedback.Play(0,0,true);Pulse(slot,.3f,.1f);}
 public void Impacted(int slot,float speed){Impacts++;if(soundCooldown[slot]>0)return;soundCooldown[slot]=.25f;feedback.Play(1,0,true);Pulse(slot,Mathf.Clamp01(speed*.05f),.1f);}
 public override void ExtraAction(string key){if(Stage!=SumoStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")Timer=-1;ConsumeActions();}
 protected override void Present(float dt){if(broadcast==null)return;float radius=Stage==SumoStage.Replay?Mathf.Max(minimumRadius,replay.ghosts[4].localScale.x):Mathf.Max(minimumRadius,Radius);var offset=Stage==SumoStage.Replay&&replay.Angle==1?new Vector3(18,16,-7):Stage==SumoStage.Replay&&replay.Angle==2?new Vector3(-18,14,8):new Vector3(0,15,-26);broadcast.Pose(Vector3.up*.3f,offset,58,true);fit.arenaBounds=new Bounds(Vector3.up*.45f,new Vector3((radius+1)*2,2.5f,(radius+1)*2));fit.Apply();}
 protected override void StopGame(){replay?.End();if(fighters!=null)foreach(var fighter in fighters){fighter.truck.Power(false);fighter.truck.body.isKinematic=true;fighter.StopAudio();}}
 protected override void StopSounds(){if(fighters!=null)foreach(var fighter in fighters)if(fighter!=null)fighter.StopAudio();}
}
}
